// contractAssertMatchZeroOnError asserts Match returns zero alongside any error.
func contractAssertMatchZeroOnError(
	tb testing.TB,
	c Contract,
	fx ContractFixture,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := c.Match(ctx, fx.Value())
	if err == nil {
		tb.Skip("Match answered for a cancelled context, so this check has no error to inspect")
	}

	var zero bool
	if got != zero {
		tb.Errorf("Match must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

